<section class="form-section"><header><h2><?= esc(lang('UI.settingsSubscription')) ?></h2></header><dl class="settings-summary"><div><dt><?= esc(lang('UI.settingsCurrentPlan')) ?></dt><dd><?= esc($subscription_plan['name']??lang('TenantMisc.unassigned')) ?></dd></div><div><dt><?= esc(lang('UserRole.status')) ?></dt><dd><?= esc($subscription['status']??lang('TenantMisc.none')) ?></dd></div><div><dt><?= esc(lang('UI.settingsLatestRequest')) ?></dt><dd><?php if(!empty($latest_plan_request)): ?><?= esc($latest_plan_request['status']??'') ?> · <?= esc($latest_plan_request['created_at']??'') ?><?php else: ?><?= esc(lang('UI.settingsNoPlanRequestsYet')) ?><?php endif; ?></dd></div></dl></section><section class="form-section"><header><h2><?= esc(lang('UI.settingsRequestNewPlan')) ?></h2></header><form method="post" action="<?= base_url('settings/plan-request') ?>" data-settings-form><?= csrf_field() ?><div class="settings-request-fields"><div class="form-field"><label for="setting-plan_id"><?= esc(lang('UI.settingsPlan')) ?></label><select name="plan_id" id="setting-plan_id" required><option value=""><?= esc(lang('UI.settingsSelectPlan')) ?></option><?php foreach($plans??[] as $plan): ?><option value="<?= (int)$plan['id'] ?>"><?= esc($plan['name']) ?></option><?php endforeach; ?></select></div><div class="form-field"><label for="setting-duration"><?= esc(lang('UI.settingsDuration')) ?></label><select name="duration" id="setting-duration"><?php foreach(['monthly'=>'UI.settingsDurationMonthly','yearly'=>'UI.settingsDurationYearly','lifetime'=>'UI.settingsDurationLifetime'] as $value=>$label): ?><option value="<?= $value ?>"><?= esc(lang($label)) ?></option><?php endforeach; ?></select></div><div class="form-field"><label for="setting-reason"><?= esc(lang('UI.settingsReason')) ?></label><input name="reason" id="setting-reason" value="<?= esc(old('reason'),'attr') ?>"></div></div><footer class="settings-save"><button class="button primary" type="submit" <?= $settingsEdit?'':'disabled' ?>><?= esc(lang('UI.settingsSubmitRequest')) ?></button></footer></form></section>
